import type { Projectile, Tank, Vec } from '../core/types';
import { actorAngle, actorDirection, actorHeading } from './actor-movement';
import { displayPixel } from '../core/display-values';
import { tankHitDetail } from './hit-location';
import { projectileImpact } from './effects';
import { projectileOutside } from './projectile-boundary';
import type { World } from './world';

export class HomingTargetReadError extends Error {}
const homing = (b: Projectile) => b.kind === 'orbital' || (b.kind === 'seeker' && b.enemy);
const size = (v: Vec) => Math.sqrt(v.x * v.x + v.y * v.y);

/** Source RotateTowardTarget does not require movTarget.parent to exist. */
function steer(world: World, b: Projectile) {
  const state = b.homing!,
    origin = world.actorParents.fieldGlobal(b, world.field);
  if (!state.target || !origin) {
    b.motion = actorDirection(0, b.speed);
    return; // The returned zero initializes motion, without writing rotation.
  }
  const target = world.actorParents.localToGlobal(state.target, tankHitDetail(state.target)),
    delta = { x: target.x - origin.x, y: target.y - origin.y };
  if (size(delta) < 5) state.close = true;
  const angle = actorHeading({ x: 0, y: 0 }, delta);
  b.angle = actorAngle(angle);
  b.motion = actorDirection(angle, b.speed);
}

/** SpawnNewBullet attaches/sets display properties before virtual Setup steering. */
export function initializeHomingProjectile(
  world: World,
  b: Projectile,
  home?: Tank,
  target?: Tank,
) {
  if (!homing(b) || b.homing) return;
  b.x = displayPixel(b.x);
  b.y = displayPixel(b.y);
  b.angle = actorAngle(b.angle);
  const tanks = world.allTanks();
  b.homing = {
    home: home ?? tanks.find((t) => t.uid === b.owner),
    target: target ?? tanks.find((t) => t.uid === b.targetId),
    avatar: world.player,
    close: false,
  };
  steer(world, b);
}

/** Inherited _-BL.Run refreshes objAvatar before MoveBullet, leaving movTarget alone. */
export function refreshHomingAvatar(world: World, b: Projectile) {
  initializeHomingProjectile(world, b);
  if (b.homing && !world.actorParents.hasParent(b.homing.avatar)) b.homing.avatar = world.player;
}

function orbit(world: World, b: Projectile, home: Tank) {
  const center = world.actorParents.point(home, world.field);
  if (!center) throw new HomingTargetReadError('Orbital read its home parent');
  const delta = { x: center.x - b.x, y: center.y - b.y };
  if (delta.x * delta.x + delta.y * delta.y > Math.pow(home.radius + 20, 2)) {
    const heading = actorHeading({ x: 0, y: 0 }, actorDirection(b.angle, 1));
    let turn = actorHeading({ x: 0, y: 0 }, delta) - heading;
    if (turn > 180) turn -= 360;
    else if (turn < -180) turn += 360;
    if (Math.abs(turn) < 15) return;
    b.angle = actorAngle(b.angle + turn / 20);
    b.motion = actorDirection(b.angle, b.speed);
  } else {
    b.angle = actorAngle(b.angle + 5);
    const offset = actorDirection(b.angle - 90, home.radius + 10);
    b.x = displayPixel(center.x + offset.x);
    b.y = displayPixel(center.y + offset.y);
    // The near branch retains moveX/moveY, including Setup's horizontal vector.
  }
}

const candidates = (world: World, b: Projectile) =>
  b.enemy ? [b.homing!.avatar, ...world.allies] : [...world.field.enemies];

function acquire(world: World, b: Projectile) {
  const point = world.actorParents.fieldGlobal(b, world.field);
  if (!point) throw new HomingTargetReadError('Orbital read its projectile parent');
  for (const tank of candidates(world, b)) {
    if (!world.actorParents.hasParent(tank))
      throw new HomingTargetReadError('Orbital acquisition read an unparented candidate');
    const center = world.actorParents.localToGlobal(tank, { x: 0, y: 0 }),
      delta = { x: center.x - point.x, y: center.y - point.y };
    if (size(delta) - tank.radius < 100) {
      b.homing!.target = tank;
      b.targetId = tank.uid; // Compatibility metadata; the stored object owns selection.
      return;
    }
  }
}

function contact(world: World, b: Projectile) {
  const state = b.homing!,
    motion = b.motion!;
  // This subclass retry follows steering. Usually base Run already refreshed
  // objAvatar, so it does not replace the separately retained movTarget.
  if (b.kind === 'seeker' && !world.actorParents.hasParent(state.avatar)) {
    state.avatar = state.target = world.player;
    b.targetId = world.player.uid;
  }
  const point = world.actorParents.fieldGlobal(b, world.field);
  if (!point) throw new HomingTargetReadError('Homing contact read its projectile parent');
  const at = (offset: number) =>
    world.actorParents.fieldLocal(
      {
        x: point.x + motion.x * offset,
        y: point.y + motion.y * offset,
      },
      world.field,
    )!;
  for (const shot of world.bullets)
    if (
      shot.enemy !== b.enemy &&
      [0, -0.5, 0.5].some((offset) => {
        const p = at(offset);
        return world.hitProjectile(shot, p.x, p.y);
      })
    ) {
      projectileImpact(world, b);
      return true;
    }
  for (const tank of b.kind === 'seeker' ? [state.avatar] : candidates(world, b)) {
    const center = world.actorParents.point(tank, world.field);
    const hit = (offset: number) => {
      if (!center || !world.actorParents.onStage(tank)) return false;
      const p = at(offset);
      return world.hitTest(tank, p.x + tank.x - center.x, p.y + tank.y - center.y);
    };
    if (state.close || hit(0) || hit(-0.5)) {
      projectileImpact(world, b);
      world.damage(tank, b.damage, b);
      return true;
    }
  }
  return false;
}

/** _-QM/_-JX MoveBullet: home/wipe, wall, steering/orbit+acquire, contact, separate writes. */
export function tickHomingProjectile(world: World, b: Projectile) {
  initializeHomingProjectile(world, b);
  const state = b.homing!;
  if (
    (b.kind === 'orbital' && (!state.home || !world.actorParents.hasParent(state.home))) ||
    b.wipe
  ) {
    projectileImpact(world, b);
    b.dead = true;
    return;
  }
  if (projectileOutside(world, b)) {
    world.addCombatEffect(b, 'impact');
    b.dead = true;
    return;
  }
  if (b.kind === 'seeker' || (state.target && world.actorParents.hasParent(state.target)))
    steer(world, b);
  else {
    orbit(world, b, state.home!);
    acquire(world, b);
  }
  if (contact(world, b)) {
    b.dead = true;
    return;
  }
  b.x = displayPixel(b.x + b.motion!.x);
  b.y = displayPixel(b.y + b.motion!.y);
}

import { expect, test } from 'bun:test';
import type { Projectile } from '../src/game/core/types';
import { STARTER } from '../src/game/data/catalog';
import { createProjectile } from '../src/game/simulation/create-projectile';
import { tickBullet } from '../src/game/simulation/projectiles';
import { createTank } from '../src/game/simulation/tank';
import { World, emptyInput } from '../src/game/simulation/world';

function setup() {
  const world = new World([], [], 18);
  world.hitTest = world.hitProjectile = () => false;
  world.player.life = world.player.maxLife = 100;
  return world;
}
function enemy(world: World, x: number, y = 0) {
  const tank = createTank(
    world.nextId(),
    { ...STARTER, avatar: false, life: 100, speed: 0, parts: [STARTER.parts[0]] },
    'enemy',
    x,
    y,
  );
  world.field.enemies.push(tank);
  return tank;
}
function shot(world: World, changes: Partial<Projectile> = {}) {
  const bullet = createProjectile(world.nextId(), {
    owner: world.player.uid,
    enemy: false,
    kind: 'orbital',
    symbol: 2016,
    x: 0,
    y: 0,
    angle: 90,
    speed: 3,
    damage: 7,
    ...changes,
  });
  world.actorParents.sync(world);
  world.addBullet(bullet);
  return bullet;
}
const tick = (world: World, bullet: Projectile) => {
  world.actorParents.sync(world);
  tickBullet(world, bullet, emptyInput());
};
const effects = (world: World) => world.runtimeFor(world.field).effectQueue;

test('orbital Setup with no target retains rotation but initializes horizontal movement', () => {
  const world = setup(),
    b = shot(world, { angle: 123 });
  expect(b.angle).toBe(123);
  expect(b.motion).toEqual({ x: 3, y: 0 });
  tick(world, b);
  expect(b.angle).toBe(128);
  expect([b.x, b.y]).toEqual([28.6, 20]); // Separate orbit placement and motion writes.
  expect(b.motion).toEqual({ x: 3, y: 0 });
});

test('distant orbital keeps movement below15 degrees, but updates it at the inclusive turn threshold', () => {
  const world = setup(),
    aligned = shot(world, { x: 100, angle: 170 });
  tick(world, aligned);
  expect([aligned.angle, aligned.x, aligned.y]).toEqual([170, 103, 0]);
  const turning = shot(world, { x: 100, angle: 165 });
  tick(world, turning);
  expect(turning.angle).toBeCloseTo(165.75);
  expect([turning.x, turning.y]).toEqual([97.05, 0.7]);
});

test('orbital acquisition follows the orbit placement, uses strict range and first array order, then aims next frame', () => {
  const world = setup(),
    b = shot(world),
    point = { x: 32.35, y: 2.8 };
  const boundary = enemy(world, point.x, point.y),
    selected = enemy(world, point.x, point.y),
    closer = enemy(world, point.x, point.y);
  boundary.x += 100 + boundary.radius;
  selected.x += 99 + selected.radius;
  closer.x += 10;
  tick(world, b);
  expect(b.targetId).toBe(selected.uid);
  expect(b.homing!.target).toBe(selected);
  expect(b.angle).toBe(95);
  tick(world, b);
  expect(b.angle).toBe(0); // Both stored y values are2.8 after Point/display conversion.
  expect(b.homing!.target).not.toBe(closer);
});

test('enemy seekers and orbitals steer toward rotated authored hit locations, not tank centers', () => {
  for (const orbital of [false, true]) {
    const world = setup(),
      target = orbital ? enemy(world, 100) : world.player;
    target.x = 100;
    target.design = { ...target.design, parts: [{ ...STARTER.parts[0], x: 30 }] };
    target.rotation = 90;
    const b = shot(world, {
      kind: orbital ? 'orbital' : 'seeker',
      enemy: !orbital,
      targetId: target.uid,
      symbol: orbital ? 2016 : 1809,
    });
    expect(b.angle).toBeCloseTo((Math.atan2(30, 100) * 180) / Math.PI);
    tick(world, b);
    expect([b.x, b.y]).toEqual([2.85, 0.85]);
  }
});

test('orbital close latch hits the first candidate even when its aimed target is later in the array', () => {
  const world = setup(),
    first = enemy(world, -200),
    aimed = enemy(world, 4),
    b = shot(world, { targetId: aimed.uid });
  expect(b.homing!.close).toBe(true); // Setup already executes RotateTowardTarget.
  aimed.x = 40;
  tick(world, b);
  expect(b.dead).toBe(true);
  expect([first.life, aimed.life]).toEqual([93, 100]);
  expect(b.hit.size).toBe(0);
  expect(b.missExempt).toBeUndefined();
  expect(world.stats.damageDone).toBe(0);
  expect(effects(world).map((effect) => effect.symbol)).toEqual([1767]);
});

test('enemy seeker close latch uses strict5px and survives later steering away from the avatar', () => {
  for (const x of [4.99, 5]) {
    const world = setup();
    world.player.x = x;
    const b = shot(world, {
      kind: 'seeker',
      symbol: 1809,
      enemy: true,
      targetId: world.player.uid,
    });
    world.player.x = 100;
    tick(world, b);
    expect(b.dead).toBe(x < 5);
    expect(world.player.life).toBe(x < 5 ? 93 : 100);
  }
});

test('orbital interception samples retained movement before tank contact and leaves the intercepting shot intact', () => {
  const world = setup(),
    b = shot(world),
    opposite = shot(world, { kind: 'shell', symbol: 1717, enemy: true });
  opposite.dead = true; // Still in arrBullets until the field flushes its removal queue.
  const point = { x: 32.35, y: 2.8 },
    calls: number[][] = [];
  world.hitProjectile = (target, x, y) => {
    expect(target).toBe(opposite);
    calls.push([x, y]);
    return Math.abs(x - (point.x + 1.5)) < 0.001;
  };
  world.hitTest = () => {
    throw new Error('shot interception must precede tank tests');
  };
  tick(world, b);
  expect(b.dead).toBe(true);
  expect(calls).toHaveLength(3);
  for (const [i, offset] of [0, -1.5, 1.5].entries()) {
    expect(calls[i][0]).toBeCloseTo(point.x + offset);
    expect(calls[i][1]).toBeCloseTo(point.y);
  }
  expect(world.bullets).toContain(opposite);
  expect(effects(world).map((effect) => effect.symbol)).toEqual([1767]);
});

test('owner detachment wipes orbitals before wall reporting; a dead but attached owner remains valid', () => {
  const world = setup(),
    b = shot(world);
  world.player.dead = true;
  tick(world, b);
  expect(b.dead).toBe(false);
  world.player = createTank(world.nextId(), STARTER, 'player');
  b.x = 1000;
  tick(world, b);
  expect(b.dead).toBe(true);
  expect(world.stats.friendlyMissed).toBe(0);
  expect(effects(world).map((effect) => effect.symbol)).toEqual([1767]);
});

test('a lethal owner callback leaves its orbital attached until queued enemy removal', () => {
  const world = setup(),
    home = enemy(world, 0),
    b = shot(world, { owner: home.uid, enemy: true, symbol: 1807 });
  world.player.x = 300;
  world.kill(home);
  expect(b.dead).toBe(false);
  tick(world, b);
  expect(b.dead).toBe(false);
  world.flushEnemyRemovals();
  tick(world, b);
  expect(b.dead).toBe(true);
  expect(effects(world).map((effect) => effect.symbol)).toEqual([1767]);
});

test('base Run refreshes collision avatar before Move while steering keeps the detached target reference', () => {
  const world = setup(),
    old = world.player;
  const b = shot(world, {
    kind: 'seeker',
    symbol: 1809,
    enemy: true,
    targetId: old.uid,
    x: 200,
    y: 100,
  });
  world.player = createTank(world.nextId(), STARTER, 'player', 0, 0, 100, 100);
  tick(world, b);
  expect(b.homing!.avatar).toBe(world.player);
  expect(b.homing!.target).toBe(old);
  // Detached Avatar.localToGlobal(hitPoint) is at its own origin, rather
  // than the new avatar's centered game root. The projectile starts at475,325 globally.
  expect(b.angle).toBe((360 * Math.atan2(-325, -475)) / (2 * Math.PI));
  let receiver: unknown;
  world.hitTest = (tank) => {
    receiver = tank;
    return true;
  };
  tick(world, b);
  expect(receiver).toBe(world.player);
  expect(world.player.life).toBe(93);
  expect(old.life).toBe(100);
  expect(b.homing!.target).toBe(old);
});

